  I18N.dict.en["app.794"] = "Calculated from the share of online sales (last N days) over total sales (sales statistics period); used for inventory allocation and replenishment calculation. The share and allocated stock follow the sales statistics period."; I18N.dict.id["app.794"] = "Dihitung dari proporsi penjualan online (N hari terakhir) terhadap total penjualan (periode statistik penjualan); digunakan untuk alokasi persediaan dan perhitungan pengadaan. Proporsi dan stok terbagi mengikuti periode statistik penjualan.";
  I18N.dict.en["app.795"] = "Calculated from the share of offline sales (last N days) over total sales (sales statistics period); used for inventory allocation and replenishment calculation. The share and allocated stock follow the sales statistics period."; I18N.dict.id["app.795"] = "Dihitung dari proporsi penjualan offline (N hari terakhir) terhadap total penjualan (periode statistik penjualan); digunakan untuk alokasi persediaan dan perhitungan pengadaan. Proporsi dan stok terbagi mengikuti periode statistik penjualan.";
  I18N.dict.en["app.796"] = "A PO has been created, but the PI quantity is not yet confirmed. This is potential supply and does not mean it will definitely ship."; I18N.dict.id["app.796"] = "PO telah dibuat, tetapi jumlah PI belum dikonfirmasi. Ini adalah pasokan potensial dan tidak berarti pasti dikirim.";
  I18N.dict.en["app.797"] = "Current available stock + in-transit stock + PO pending PI + PI confirmed not shipped. Used to judge whether replenishment is needed overall."; I18N.dict.id["app.797"] = "Persediaan tersedia saat ini + stok dalam perjalanan + PO menunggu PI + PI dikonfirmasi belum dikirim. Digunakan untuk menilai apakah pengadaan diperlukan secara keseluruhan.";
  I18N.dict.en["app.798"] = "Total inventory pool ÷ average monthly sales (sales statistics period). Indicates roughly how many months the total stock can still sell, excluding in-transit and unshipped orders."; I18N.dict.id["app.798"] = "Total pool persediaan ÷ rata-rata penjualan bulanan (periode statistik penjualan). Menunjukkan kira-kira berapa bulan total stok masih dapat terjual, tanpa memperhitungkan yang dalam perjalanan dan pesanan belum dikirim.";
  I18N.dict.en["app.799"] = "No Sales"; I18N.dict.id["app.799"] = "Tidak Ada Penjualan";
  I18N.dict.en["app.800"] = "PI confirmed, but the factory has not yet shipped the quantity. Closer to actual supply than PO pending PI."; I18N.dict.id["app.800"] = "PI dikonfirmasi, tetapi pabrik belum mengirim jumlahnya. Lebih dekat dengan pasokan aktual daripada PO menunggu PI.";
  I18N.dict.en["app.801"] = "Current available stock ÷ average monthly sales (sales statistics period). Indicates roughly how many months the existing stock can still sell, excluding in-transit and unshipped orders."; I18N.dict.id["app.801"] = "Persediaan tersedia saat ini ÷ rata-rata penjualan bulanan (periode statistik penjualan). Menunjukkan kira-kira berapa bulan stok yang ada masih dapat terjual, tanpa memperhitungkan yang dalam perjalanan dan pesanan belum dikirim.";
  I18N.dict.en["app.802"] = "(Current available stock + in-transit stock) ÷ average monthly sales (sales statistics period). Used to judge how long stock will last once goods in transit arrive."; I18N.dict.id["app.802"] = "(Persediaan tersedia saat ini + stok dalam perjalanan) ÷ rata-rata penjualan bulanan (periode statistik penjualan). Digunakan untuk menilai berapa lama stok bertahan setelah barang dalam perjalanan tiba.";
  I18N.dict.en["app.803"] = "(Current available stock + in-transit stock + this suggested purchase qty) ÷ average monthly sales (sales statistics period). Used to judge roughly how many months stock will last after this replenishment."; I18N.dict.id["app.803"] = "(Persediaan tersedia saat ini + stok dalam perjalanan + jumlah pembelian yang disarankan kali ini) ÷ rata-rata penjualan bulanan (periode statistik penjualan). Digunakan untuk menilai kira-kira berapa bulan stok bertahan setelah pengadaan ini.";
  I18N.dict.en["app.804"] = "The system judges the current SKU status based on rules such as sales, inventory, aging, stockouts, slow sales, and overstock."; I18N.dict.id["app.804"] = "Sistem menilai status SKU saat ini berdasarkan aturan seperti penjualan, persediaan, usia stok, kekurangan stok, penjualan lambat, dan kelebihan stok.";
  I18N.dict.en["app.805"] = "The system provides operation suggestions based on sales activity, e.g. prioritize replenishment, replenish with caution, pause replenishment, manual review."; I18N.dict.id["app.805"] = "Sistem memberikan saran operasi berdasarkan aktivitas penjualan, mis. prioritaskan pengadaan, pengadaan hati-hati, jeda pengadaan, tinjauan manual.";
  I18N.dict.en["app.806"] = "The most recent inbound date for this SKU, used to judge aging and whether it has been long without replenishment."; I18N.dict.id["app.806"] = "Tanggal masuk terakhir untuk SKU ini, digunakan untuk menilai usia stok dan apakah sudah lama tidak diasuransikan.";
  I18N.dict.en["app.807"] = "The number of days from the current date to the last inbound date. The larger the number, the longer the SKU has gone without new stock."; I18N.dict.id["app.807"] = "Jumlah hari dari tanggal saat ini ke tanggal masuk terakhir. Semakin besar angka, semakin lama SKU tidak menerima stok baru.";
  I18N.dict.en["app.808"] = "The number of sales months you want the stock to cover after replenishment. It is a calculation parameter, not an actual inventory result."; I18N.dict.id["app.808"] = "Jumlah bulan penjualan yang ingin dicakup stok setelah pengadaan. Ini adalah parameter perhitungan, bukan hasil persediaan aktual.";
  I18N.dict.en["app.809"] = "Suggested replenishment qty based on average monthly sales over the sales statistics period (last N days) and the target turnover. SKUs that are slow-selling, stagnant, or overstocked are capped at 0."; I18N.dict.id["app.809"] = "Jumlah pengadaan yang disarankan berdasarkan rata-rata penjualan bulanan selama periode statistik penjualan (N hari terakhir) dan perputaran target. SKU yang lambat terjual, stagnan, atau kelebihan stok dibatasi menjadi 0.";
  I18N.dict.en["app.810"] = "Add to PO"; I18N.dict.id["app.810"] = "Tambah ke PO";
  I18N.dict.en["app.811"] = "Calculated from the share of this channel's sales (last N days) over total sales (sales statistics period); used for inventory allocation and replenishment calculation. The share and allocated stock follow the sales statistics period."; I18N.dict.id["app.811"] = "Dihitung dari proporsi penjualan saluran ini (N hari terakhir) terhadap total penjualan (periode statistik penjualan); digunakan untuk alokasi persediaan dan perhitungan pengadaan. Proporsi dan stok terbagi mengikuti periode statistik penjualan.";
  I18N.dict.en["app.812"] = "Current Calculated Turnover"; I18N.dict.id["app.812"] = "Perputaran Terhitung Saat Ini";
  I18N.dict.en["app.813"] = "Channel allocated stock pool (allocated by sales statistics period share) ÷ channel average monthly sales (sales statistics period). Indicates roughly how many months the existing stock can still sell."; I18N.dict.id["app.813"] = "Pool stok terbagi saluran (dialokasikan berdasarkan proporsi periode statistik penjualan) ÷ rata-rata penjualan bulanan saluran (periode statistik penjualan). Menunjukkan kira-kira berapa bulan stok yang ada masih dapat terjual.";
