  I18N.dict.en["app.833"] = "The following brands have no target turnover rule configured and cannot be recalculated. Please add rules for these brands in \"⚙ Forecast Parameter Settings\" first, then recalculate:"; I18N.dict.id["app.833"] = "Merek berikut belum dikonfigurasi aturan perputaran target dan tidak dapat dihitung ulang. Silakan tambahkan aturan untuk merek ini di \"⚙ Pengaturan Parameter Perkiraan\" terlebih dahulu, lalu hitung ulang:";
  I18N.dict.en["app.834"] = "Unmatched SKU Count"; I18N.dict.id["app.834"] = "Jumlah SKU Tidak Terjangkau";
  I18N.dict.en["app.835"] = "Tip: simply add a brand-level rule (leave country/warehouse blank) to cover all countries/warehouses of that brand."; I18N.dict.id["app.835"] = "Tips: cukup tambahkan aturan tingkat merek (biarkan negara/gudang kosong) untuk mencakup semua negara/gudang merek tersebut.";
