  I18N.dict.en["app.860"] = "Warehouse:"; I18N.dict.id["app.860"] = "Gudang:";
  I18N.dict.en["app.861"] = "② Rule object saved this time (editable; defaults to prefilling the current filter)"; I18N.dict.id["app.861"] = "② Objek aturan yang disimpan kali ini (dapat diedit; default mengisi filter saat ini)";
  I18N.dict.en["app.862"] = "Blank = wildcard (no restriction on this dimension). Match priority: Brand+Country+Warehouse > Brand+Country > Brand+Warehouse > Brand > Country+Warehouse > Country > Warehouse > Fully Wildcard. No fallback value — unmatched SKUs will block recalculation. Save uses this section as the source of truth."; I18N.dict.id["app.862"] = "Kosong = wildcard (tidak ada batasan pada dimensi ini). Prioritas kecocokan: Merek+Negara+Gudang > Merek+Negara > Merek+Gudang > Merek > Negara+Gudang > Negara > Gudang > Wildcard Penuh. Tidak ada nilai fallback — SKU yang tidak terjangkau akan menghalangi perhitungan ulang. Penyimpanan menggunakan bagian ini sebagai acuan.";
  I18N.dict.en["app.863"] = "(empty = wildcard)"; I18N.dict.id["app.863"] = "(kosong = wildcard)";
  I18N.dict.en["app.864"] = "Currently matched existing rule (read-only; before saving you can see which rule will be overwritten/added)"; I18N.dict.id["app.864"] = "Aturan yang ada saat ini yang terjangkau (hanya baca; sebelum menyimpan Anda dapat melihat aturan mana yang akan ditimpa/ditambah)";
  I18N.dict.en["app.865"] = "⚠️ Currently Brand / Country / Warehouse are all \"All\". Saving will generate a fully wildcard rule that applies to all dimensions not covered by more specific rules. Please confirm this is intended."; I18N.dict.id["app.865"] = "⚠️ Saat ini Merek / Negara / Gudang semuanya \"Semua\". Menyimpan akan menghasilkan aturan wildcard penuh yang berlaku untuk semua dimensi yang tidak dicakup oleh aturan lebih spesifik. Silakan konfirmasi ini memang diinginkan.";
  I18N.dict.en["app.866"] = "⚙ Advanced Settings (manually maintain other dimension rules) ▾"; I18N.dict.id["app.866"] = "⚙ Pengaturan Lanjutan (kelola aturan dimensi lain secara manual) ▾";
  I18N.dict.en["app.867"] = "The following are all configured rules; you may manually add, delete, or edit rules beyond the current filter dimension. They are merged on save (the current dimension rule follows the left input box)."; I18N.dict.id["app.867"] = "Berikut adalah semua aturan yang dikonfigurasi; Anda dapat menambah, menghapus, atau mengedit aturan di luar dimensi filter saat ini. Digabungkan saat menyimpan (aturan dimensi saat ini mengikuti kotak input kiri).";
  I18N.dict.en["app.868"] = "+ Add Rule"; I18N.dict.id["app.868"] = "+ Tambah Aturan";
  I18N.dict.en["app.869"] = "After saving, click \"Recalculate\" to apply the new parameters."; I18N.dict.id["app.869"] = "Setelah menyimpan, klik \"Hitung Ulang\" untuk menerapkan parameter baru.";
