  I18N.dict.en["html.addCIRow"] = "<div class=\"flex gap-8 mb-8\" id=\"ci-r-{v1}\"><input type=\"text\" placeholder=\"SKU\" id=\"ci-rs-{v2}\" style=\"flex:1\"><input type=\"number\" placeholder=\"Shipment Quantity\" id=\"ci-rq-{v3}\" style=\"width:105px\"><input type=\"number\" step=\"0.01\" placeholder=\"Unit Price\" id=\"ci-rp-{v4}\" style=\"width:110px\"><input type=\"number\" min=\"0\" step=\"0.01\" placeholder=\"Actual Customs Duty Rate(%)\" id=\"ci-rr-{v5}\" style=\"width:145px\"><button class=\"btn btn-danger btn-sm\" onclick=\"document.getElementById('ci-r-{v6}').remove()\">🗑️</button></div>"; I18N.dict.id["html.addCIRow"] = "<div class=\"flex gap-8 mb-8\" id=\"ci-r-{v1}\"><input type=\"text\" placeholder=\"SKU\" id=\"ci-rs-{v2}\" style=\"flex:1\"><input type=\"number\" placeholder=\"Jumlah Pengiriman\" id=\"ci-rq-{v3}\" style=\"width:105px\"><input type=\"number\" step=\"0.01\" placeholder=\"Harga Satuan\" id=\"ci-rp-{v4}\" style=\"width:110px\"><input type=\"number\" min=\"0\" step=\"0.01\" placeholder=\"Tarif Bea Masuk Aktual(%)\" id=\"ci-rr-{v5}\" style=\"width:145px\"><button class=\"btn btn-danger btn-sm\" onclick=\"document.getElementById('ci-r-{v6}').remove()\">🗑️</button></div>";
  I18N.dict.en["modal.title.createBalPay"] = "Create Balance Payment Request - {v1}"; I18N.dict.id["modal.title.createBalPay"] = "Buat Permintaan Pembayaran Sisa - {v1}";
  I18N.dict.en["modal.body.createBalPay"] = "<div class=\"form-card\" style=\"box-shadow:none;padding:0\"><div class=\"detail-grid mb-16\"><div class=\"detail-item\"><span class=\"detail-label\">CIAmount</span><span class=\"detail-value\">{v1}</span></div><div class=\"detail-item\"><span class=\"detail-label\">Deposit Deducted</span><span class=\"detail-value\">{v2}</span></div><div class=\"detail-item\"><span class=\"detail-label\">Payable Balance</span><span class=\"detail-value font-bold\">{v3}</span></div></div><div class=\"form-grid\"><div class=\"form-group\"><label>Deduct?</label><select id=\"bal-ded\" onchange=\"document.getElementById('bal-ded-amt').disabled=this.value==='0'\"><option value=\"0\">No</option><option value=\"1\">Yes</option></select></div><div class=\"form-group\"><label>Deduction Amount</label><input type=\"number\" step=\"0.01\" id=\"bal-ded-amt\" value=\"0\" disabled></div><div class=\"form-group\"><label>Deduction Source Type</label><select id=\"bal-ded-type\"><option value=\"\">Select</option><option value=\"other_payment\">Other Overpayment</option><option value=\"price_diff\">Price Variance</option><option value=\"quality_claim\">Quality Claim</option><option value=\"advance_payment\">Advance Payment Deduction</option><option value=\"other\">Other</option></select></div><div class=\"form-group\"><label>Deduction Reference No.</label><input type=\"text\" id=\"bal-ded-ref\"></div><div class=\"form-group form-group-full\"><label>Deduction Note</label><textarea id=\"bal-ded-desc\" rows=\"2\"></textarea></div></div></div>"; I18N.dict.id["modal.body.createBalPay"] = "<div class=\"form-card\" style=\"box-shadow:none;padding:0\"><div class=\"detail-grid mb-16\"><div class=\"detail-item\"><span class=\"detail-label\">CIJumlah</span><span class=\"detail-value\">{v1}</span></div><div class=\"detail-item\"><span class=\"detail-label\">Deposit Dikurangi</span><span class=\"detail-value\">{v2}</span></div><div class=\"detail-item\"><span class=\"detail-label\">Sisa Payable</span><span class=\"detail-value font-bold\">{v3}</span></div></div><div class=\"form-grid\"><div class=\"form-group\"><label>Potong?</label><select id=\"bal-ded\" onchange=\"document.getElementById('bal-ded-amt').disabled=this.value==='0'\"><option value=\"0\">Tidak</option><option value=\"1\">Ya</option></select></div><div class=\"form-group\"><label>Jumlah Potongan</label><input type=\"number\" step=\"0.01\" id=\"bal-ded-amt\" value=\"0\" disabled></div><div class=\"form-group\"><label>Tipe Sumber Potongan</label><select id=\"bal-ded-type\"><option value=\"\">Pilih</option><option value=\"other_payment\">Kelebihan Bayar Lainnya</option><option value=\"price_diff\">Selisih Harga</option><option value=\"quality_claim\">Klaim Kualitas</option><option value=\"advance_payment\">Potongan Uang Muka</option><option value=\"other\">Lainnya</option></select></div><div class=\"form-group\"><label>No. Referensi Potongan</label><input type=\"text\" id=\"bal-ded-ref\"></div><div class=\"form-group form-group-full\"><label>Keterangan Potongan</label><textarea id=\"bal-ded-desc\" rows=\"2\"></textarea></div></div></div>";
  I18N.dict.en["modal.footer.createBalPay"] = "<button class=\"btn btn-secondary\" onclick=\"closeModal()\">Cancel</button><button class=\"btn btn-primary\" onclick=\"saveBalPay('{v1}')\">Create</button>"; I18N.dict.id["modal.footer.createBalPay"] = "<button class=\"btn btn-secondary\" onclick=\"closeModal()\">Batal</button><button class=\"btn btn-primary\" onclick=\"saveBalPay('{v1}')\">Buat</button>";
  I18N.dict.en["modal.title.viewCICost"] = "CIExpense Management - {v1}"; I18N.dict.id["modal.title.viewCICost"] = "CIManajemen Biaya - {v1}";
