  I18N.dict.en["gen.L5056.1"] = "<div style=\"font-size:12px;color:#888;margin-top:8px\">Tip: Add a brand-level rule (leave Country/Warehouse blank) to cover all countries and warehouses for that brand.</div>"; I18N.dict.id["gen.L5056.1"] = "<div style=\"font-size:12px;color:#888;margin-top:8px\">Kiat: Tambahkan aturan tingkat merek (biarkan Negara/Gudang kosong) untuk mencakup semua negara dan gudang bagi merek tersebut.</div>";
