  I18N.dict.en["gen.L5154.1"] = "<div style=\"font-size:12px;color:#888;margin-top:4px\">Monthly average sales, current available turnover, current turnover, current calculated turnover, post-transit turnover, post-order turnover, estimated turnover months, share, allocated inventory, and suggested purchase quantity are calculated using the current Sales Statistics Period. Only the classification, risk, and blocking layer (sales activity status and risk labels) still uses the last four months. This is an intentional phased split, not a bug.</div>"; I18N.dict.id["gen.L5154.1"] = "<div style=\"font-size:12px;color:#888;margin-top:4px\">Rata-rata penjualan bulanan, perputaran tersedia saat ini, perputaran saat ini, perputaran hasil perhitungan saat ini, perputaran setelah barang dalam perjalanan, perputaran setelah pemesanan, estimasi bulan perputaran, proporsi, persediaan yang dialokasikan, dan jumlah pembelian yang disarankan dihitung menggunakan Periode Statistik Penjualan saat ini. Hanya lapisan klasifikasi, risiko, dan pemblokiran (status aktivitas penjualan dan label risiko) yang masih menggunakan dasar empat bulan terakhir. Ini adalah pemisahan bertahap yang disengaja, bukan bug.</div>";
  I18N.dict.en["gen.L5157.1"] = "<label style=\"font-weight:600;display:block;margin-bottom:8px\">Target Turnover Configuration</label>"; I18N.dict.id["gen.L5157.1"] = "<label style=\"font-weight:600;display:block;margin-bottom:8px\">Konfigurasi Target Perputaran</label>";
  I18N.dict.en["gen.L5159.1"] = "<div style=\"font-weight:600;color:#444;margin-bottom:6px\">① Current page filter (read-only reference)</div>"; I18N.dict.id["gen.L5159.1"] = "<div style=\"font-weight:600;color:#444;margin-bottom:6px\">① Filter halaman saat ini (referensi hanya-baca)</div>";
  I18N.dict.en["gen.L5160.1"] = "Currently viewing: "; I18N.dict.id["gen.L5160.1"] = "Saat ini melihat: ";
  I18N.dict.en["gen.L5161.1"] = "<span style=\"display:inline-block;padding:2px 8px;margin:0 3px;background:#fff;border:1px solid #ccc;border-radius:10px\">Brand: "; I18N.dict.id["gen.L5161.1"] = "<span style=\"display:inline-block;padding:2px 8px;margin:0 3px;background:#fff;border:1px solid #ccc;border-radius:10px\">Merek: ";
  I18N.dict.en["gen.L5162.1"] = "<span style=\"display:inline-block;padding:2px 8px;margin:0 3px;background:#fff;border:1px solid #ccc;border-radius:10px\">Country: "; I18N.dict.id["gen.L5162.1"] = "<span style=\"display:inline-block;padding:2px 8px;margin:0 3px;background:#fff;border:1px solid #ccc;border-radius:10px\">Negara: ";
  I18N.dict.en["gen.L5163.1"] = "<span style=\"display:inline-block;padding:2px 8px;margin:0 3px;background:#fff;border:1px solid #ccc;border-radius:10px\">Warehouse: "; I18N.dict.id["gen.L5163.1"] = "<span style=\"display:inline-block;padding:2px 8px;margin:0 3px;background:#fff;border:1px solid #ccc;border-radius:10px\">Gudang: ";
  I18N.dict.en["gen.L5166.1"] = "<div style=\"font-weight:600;color:#2c5d8a;margin-bottom:6px\">② Rule object to save (editable, pre-filled by default with current filter)</div>"; I18N.dict.id["gen.L5166.1"] = "<div style=\"font-weight:600;color:#2c5d8a;margin-bottom:6px\">② Objek aturan untuk disimpan (dapat diubah, secara bawaan diisi dengan filter saat ini)</div>";
  I18N.dict.en["gen.L5167.1"] = "<div style=\"font-size:12px;color:#888;margin-bottom:8px\">Blank = wildcard (no restriction on this dimension). Match priority: Brand+Country+Warehouse &gt; Brand+Country &gt; Brand+Warehouse &gt; Brand &gt; Country+Warehouse &gt; Country &gt; Warehouse &gt; Full Wildcard. <b>No fallback value</b>—unmatched SKUs will block recalculation. The values here are used when saving.</div>"; I18N.dict.id["gen.L5167.1"] = "<div style=\"font-size:12px;color:#888;margin-bottom:8px\">Kosong = semua nilai (dimensi ini tidak dibatasi). Prioritas pencocokan: Merek+Negara+Gudang &gt; Merek+Negara &gt; Merek+Gudang &gt; Merek &gt; Negara+Gudang &gt; Negara &gt; Gudang &gt; Semua Dimensi. <b>Tidak ada nilai cadangan</b>—SKU yang tidak cocok akan memblokir penghitungan ulang. Nilai di sini digunakan saat menyimpan.</div>";
  I18N.dict.en["gen.L5169.1"] = "<div><label style=\"font-size:12px;color:#666\">Brand</label><input type=\"text\" id=\"rp-rule-brand\" class=\"form-control input-sm\" value=\""; I18N.dict.id["gen.L5169.1"] = "<div><label style=\"font-size:12px;color:#666\">Merek</label><input type=\"text\" id=\"rp-rule-brand\" class=\"form-control input-sm\" value=\"";
  I18N.dict.en["gen.L5169.2"] = "\" placeholder=\"(Blank = wildcard)\" style=\"width:120px\"></div>"; I18N.dict.id["gen.L5169.2"] = "\" placeholder=\"(Kosong = semua nilai)\" style=\"width:120px\"></div>";
  I18N.dict.en["gen.L5170.1"] = "<div><label style=\"font-size:12px;color:#666\">Country</label><input type=\"text\" id=\"rp-rule-country\" class=\"form-control input-sm\" value=\""; I18N.dict.id["gen.L5170.1"] = "<div><label style=\"font-size:12px;color:#666\">Negara</label><input type=\"text\" id=\"rp-rule-country\" class=\"form-control input-sm\" value=\"";
  I18N.dict.en["gen.L5170.2"] = "\" placeholder=\"(Blank = wildcard)\" style=\"width:120px\"></div>"; I18N.dict.id["gen.L5170.2"] = "\" placeholder=\"(Kosong = semua nilai)\" style=\"width:120px\"></div>";
  I18N.dict.en["gen.L5171.1"] = "<div><label style=\"font-size:12px;color:#666\">Warehouse</label><input type=\"text\" id=\"rp-rule-warehouse\" class=\"form-control input-sm\" value=\""; I18N.dict.id["gen.L5171.1"] = "<div><label style=\"font-size:12px;color:#666\">Gudang</label><input type=\"text\" id=\"rp-rule-warehouse\" class=\"form-control input-sm\" value=\"";
