  I18N.dict.en["gen.L5174.1"] = "<div><label style=\"font-size:12px;color:#666\">Online Turnover</label><input type=\"number\" id=\"rp-param-online\" class=\"form-control input-sm\" value=\""; I18N.dict.id["gen.L5174.1"] = "<div><label style=\"font-size:12px;color:#666\">Perputaran Online</label><input type=\"number\" id=\"rp-param-online\" class=\"form-control input-sm\" value=\"";
