  I18N.dict.en["gen.L5181.1"] = "<label style=\"font-weight:600;display:block;margin-bottom:6px\">Currently matched existing rule (read-only, shows which will be overwritten/added before saving)</label>"; I18N.dict.id["gen.L5181.1"] = "<label style=\"font-weight:600;display:block;margin-bottom:6px\">Aturan yang sudah ada yang cocok saat ini (hanya-baca, menampilkan yang akan ditimpa/ditambah sebelum disimpan)</label>";
  I18N.dict.en["gen.L5185.1"] = "<div style=\"margin-bottom:14px;padding:10px;background:#fdecea;border:1px solid #f5c6cb;border-radius:6px;color:#c0392b;font-size:13px\">⚠️ Brand/Country/Warehouse are all set to \"All\". Saving will create a <b>full wildcard rule</b> that applies wherever no more specific rule exists. Confirm that this is intended.</div>"; I18N.dict.id["gen.L5185.1"] = "<div style=\"margin-bottom:14px;padding:10px;background:#fdecea;border:1px solid #f5c6cb;border-radius:6px;color:#c0392b;font-size:13px\">⚠️ Merek/Negara/Gudang semuanya diatur ke \"Semua\". Menyimpan akan membuat <b>aturan untuk semua dimensi</b> yang berlaku jika tidak ada aturan yang lebih spesifik. Konfirmasikan bahwa ini memang diinginkan.</div>";
  I18N.dict.en["gen.L5188.1"] = "<div style=\"cursor:pointer;font-weight:600;color:#555;font-size:13px;user-select:none\" onclick=\"toggleRpAdv()\">⚙ Advanced Settings (manually manage other dimension rules) ▾</div>"; I18N.dict.id["gen.L5188.1"] = "<div style=\"cursor:pointer;font-weight:600;color:#555;font-size:13px;user-select:none\" onclick=\"toggleRpAdv()\">⚙ Pengaturan Lanjutan (kelola aturan dimensi lain secara manual) ▾</div>";
  I18N.dict.en["gen.L5190.1"] = "<div style=\"font-size:12px;color:#888;margin-bottom:8px\">Below are all configured rules; you can manually add, delete, or modify rules <b>outside the current filter dimension</b>; they will be merged when saving (the current dimension rule uses the left input fields as authority).</div>"; I18N.dict.id["gen.L5190.1"] = "<div style=\"font-size:12px;color:#888;margin-bottom:8px\">Berikut adalah semua aturan yang dikonfigurasi; dapat menambah/menghapus/mengubah aturan <b>di luar dimensi filter saat ini</b> secara manual; akan digabungkan saat disimpan (aturan dimensi saat ini menggunakan input kiri sebagai patokan).</div>";
  I18N.dict.en["gen.L5191.1"] = "<table class=\"table table-bordered\" style=\"font-size:13px;margin-bottom:8px\"><thead><tr><th>Brand</th><th>Country</th><th>Warehouse</th><th>Online Turnover</th><th>Offline Turnover</th><th style=\"width:50px\"></th></tr></thead><tbody id=\"rp-dim-tbody\"></tbody></table>"; I18N.dict.id["gen.L5191.1"] = "<table class=\"table table-bordered\" style=\"font-size:13px;margin-bottom:8px\"><thead><tr><th>Merek</th><th>Negara</th><th>Gudang</th><th>Perputaran Online</th><th>Perputaran Offline</th><th style=\"width:50px\"></th></tr></thead><tbody id=\"rp-dim-tbody\"></tbody></table>";
  I18N.dict.en["gen.L5192.1"] = "<button class=\"btn btn-default btn-sm\" onclick=\"addRpDimRow()\">+ Add Rule</button>"; I18N.dict.id["gen.L5192.1"] = "<button class=\"btn btn-default btn-sm\" onclick=\"addRpDimRow()\">+ Tambah Aturan</button>";
  I18N.dict.en["gen.L5200.1"] = "<button class=\"btn btn-secondary\" onclick=\"closeModal()\">Cancel</button><button class=\"btn btn-primary\" onclick=\"saveRpParams()\">💾 Save Current Dimension Rule</button>"; I18N.dict.id["gen.L5200.1"] = "<button class=\"btn btn-secondary\" onclick=\"closeModal()\">Batal</button><button class=\"btn btn-primary\" onclick=\"saveRpParams()\">💾 Simpan Aturan Dimensi Saat Ini</button>";
