  I18N.dict.en["gen.L5247.1"] = "Target turnover multidimensional defaults (JSON array): brand/country/warehouse/online_turnover/offline_turnover. Blank = wildcard. Match priority: Brand+Country+Warehouse>Brand+Country>Brand+Warehouse>Brand>Country+Warehouse>Country>Warehouse>Fallback"; I18N.dict.id["gen.L5247.1"] = "Nilai bawaan multidimensi untuk target perputaran (array JSON): brand/country/warehouse/online_turnover/offline_turnover. Kosong = semua nilai. Prioritas pencocokan: Merek+Negara+Gudang>Merek+Negara>Merek+Gudang>Merek>Negara+Gudang>Negara>Gudang>Cadangan";
