  I18N.dict.en["gen.L6351.1"] = "<b>📌 Purpose of Lifecycle</b><br>"; I18N.dict.id["gen.L6351.1"] = "<b>📌 Fungsi Siklus Hidup</b><br>";
  I18N.dict.en["gen.L6352.1"] = "Lifecycle is a field that helps the system determine replenishment strategy, affecting <b>Suggested Replenishment Quantity</b> and <b>Suggested Action</b>.<br>"; I18N.dict.id["gen.L6352.1"] = "Siklus Hidup adalah kolom yang membantu sistem menentukan strategi pengisian ulang, memengaruhi <b>Jumlah Pengisian Ulang Disarankan</b> dan <b>Aksi Disarankan</b>.<br>";
  I18N.dict.en["gen.L6353.1"] = "You can adjust it manually in the <b>Product Management → Lifecycle</b> field."; I18N.dict.id["gen.L6353.1"] = "Anda dapat menyesuaikannya secara manual di kolom <b>Manajemen Produk → Siklus Hidup</b>.";
  I18N.dict.en["gen.L6356.1"] = "<thead><tr><th>Label</th><th>System Assessment Basis</th><th>Replenishment Strategy</th><th style=\"text-align:center\">Replenishment Factor</th><th style=\"text-align:center\">Replenish?</th></tr></thead>"; I18N.dict.id["gen.L6356.1"] = "<thead><tr><th>Label</th><th>Dasar Penilaian Sistem</th><th>Strategi Pengisian Ulang</th><th style=\"text-align:center\">Faktor Pengisian Ulang</th><th style=\"text-align:center\">Isi Ulang?</th></tr></thead>";
  I18N.dict.en["gen.L6362.1"] = "<span class=\"status-badge status-completed\">Yes</span>"; I18N.dict.id["gen.L6362.1"] = "<span class=\"status-badge status-completed\">Ya</span>";
  I18N.dict.en["gen.L6362.2"] = "<span class=\"status-badge status-secondary\">No</span>"; I18N.dict.id["gen.L6362.2"] = "<span class=\"status-badge status-secondary\">Tidak</span>";
  I18N.dict.en["gen.L6366.1"] = "<b>💡 Formula</b><br>"; I18N.dict.id["gen.L6366.1"] = "<b>💡 Rumus</b><br>";
  I18N.dict.en["gen.L6367.1"] = "Suggested Replenishment Quantity = max(0, Target Inventory − Total Inventory Pool) (Rounded by carton pack size/MOQ; Slow-Moving/Stagnant/High Stock items are forced to 0)<br>"; I18N.dict.id["gen.L6367.1"] = "Jumlah Pengisian Ulang yang Disarankan = max(0, Persediaan Target − Total Persediaan Gabungan) (Dibulatkan berdasarkan isi per karton/MOQ; item lambat terjual, stagnan, atau stok tinggi ditetapkan menjadi 0)<br>";
  I18N.dict.en["gen.L6368.1"] = "• Total Inventory Pool = Current Available + In Transit + PI Confirmed but Not Shipped + PO Quantities Not Yet Confirmed by a PI<br>"; I18N.dict.id["gen.L6368.1"] = "• Total Kumpulan Persediaan = Tersedia Saat Ini + Dalam Perjalanan + PI yang Sudah Dikonfirmasi tetapi Belum Dikirim + Jumlah PO yang Belum Dikonfirmasi oleh PI<br>";
  I18N.dict.en["gen.L6369.1"] = "• Target Inventory Months defaults to 4 (backend configuration; not adjustable in \"Forecast Parameter Settings\" at this stage)<br>"; I18N.dict.id["gen.L6369.1"] = "• Bulan Persediaan Target bernilai bawaan 4 (konfigurasi backend; belum dapat diubah di \"Pengaturan Parameter Prakiraan\" pada tahap ini)<br>";
  I18N.dict.en["gen.L6370.1"] = "• The Lifecycle Factor is not currently used to calculate Suggested Replenishment Quantity; it is used only in Suggested Action and Business Advice text<br>"; I18N.dict.id["gen.L6370.1"] = "• Faktor Siklus Hidup saat ini tidak digunakan untuk menghitung Jumlah Pengisian Ulang yang Disarankan; faktor ini hanya digunakan dalam teks Aksi yang Disarankan dan Saran Bisnis<br>";
